import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import { z } from 'zod'

import { fail, ok } from '#mcp/result'

type RpcSender = (body: Record<string, unknown>) => Promise<unknown>
type ToolHandler = (args: Record<string, unknown>) => Promise<unknown>

const MAX_CODE_OBJECT_SOURCE_LENGTH = 100_000
const CODE_OBJECT_TRUST_WARNING =
  'Code Object TSX executes as trusted in-process code, not a security sandbox. Never use external or untrusted source; route it to a sandboxed embed.'

const exactTargetSchema = {
  content_document_id: z
    .string()
    .trim()
    .min(1)
    .describe('Copy board_context.board_build_base.content_document_id exactly.'),
  document_id: z
    .string()
    .trim()
    .min(1)
    .describe('Copy board_context.board_build_base.document_id exactly.'),
  page_id: z
    .string()
    .trim()
    .min(1)
    .describe('Copy board_context.board_build_base.page_id exactly.'),
  runtime_instance_id: z
    .string()
    .trim()
    .min(1)
    .describe('Copy board_context.board_build_base.runtime_instance_id exactly.'),
  workspace_id: z
    .string()
    .trim()
    .min(1)
    .describe('Copy board_context.board_build_base.workspace_id exactly.')
}

const buildBaseSchema = z
  .object({
    ...exactTargetSchema,
    context_token: z.string().trim().min(1),
    contract: z.literal('board-build/v1'),
    expected_revision: z.number().int().nonnegative()
  })
  .strict()
  .describe('Copy board_context.board_build_base as one atomic packet.')

const extensionSchema = z
  .object({
    contract: z.literal('board-builder-extension/v1'),
    output_digest: z.string().trim().min(1).optional(),
    profile_id: z.string().trim().min(1).optional(),
    skill_id: z.string().trim().min(1),
    skill_version: z.string().trim().min(1).optional()
  })
  .strict()

const placementSchema = z
  .object({
    clearance: z.number().finite().min(0).max(512).optional(),
    preferred_directions: z
      .array(z.enum(['above', 'below', 'left', 'right']))
      .length(4)
      .optional()
  })
  .strict()

const placementTargetSchema = z.discriminatedUnion('kind', [
  z
    .object({ kind: z.literal('auto') })
    .strict()
    .describe(
      'Preferred for an ordinary prompt with no exact requested location. The builder measures the card and searches one bounded deterministic context region; omission does not mean auto.'
    ),
  z
    .object({ kind: z.literal('point'), x: z.number().finite(), y: z.number().finite() })
    .strict()
    .describe(
      'One exact artifact-center coordinate. It does not search nearby positions; account for half the artifact size plus clearance.'
    ),
  z
    .object({
      height: z.number().finite().positive(),
      kind: z.literal('region'),
      width: z.number().finite().positive(),
      x: z.number().finite(),
      y: z.number().finite()
    })
    .strict()
    .describe(
      'A bounded search region whose x/y are the top-left corner; the builder searches deterministic collision-free candidates inside it.'
    )
])

const cardPlacementSchema = placementSchema.extend({ target: placementTargetSchema.optional() })

const plainJsonObjectSchema = z.record(z.string(), z.json())
const codeObjectSourceSchema = z
  .string()
  .trim()
  .min(1)
  .max(MAX_CODE_OBJECT_SOURCE_LENGTH)
  .describe(
    `Complete authored TSX source, up to ${MAX_CODE_OBJECT_SOURCE_LENGTH} characters. Default-export one React component; import only react or react/jsx-runtime. The component receives interactionEnabled, props, state, and setState. Use setState for state that must survive Undo, duplication, save, and reopen. ${CODE_OBJECT_TRUST_WARNING}`
  )

const codeObjectCreateRecipeSchema = z
  .object({
    height: z.number().finite().min(160).max(1_200).optional(),
    initial_state: plainJsonObjectSchema.optional(),
    kind: z.literal('code_object'),
    name: z.string().trim().min(1).max(120),
    object_key: z.string().trim().min(1).max(160),
    operation: z.literal('create'),
    placement: cardPlacementSchema.optional(),
    props: plainJsonObjectSchema.optional(),
    source: codeObjectSourceSchema,
    source_format: z.literal('tsx'),
    width: z.number().finite().min(240).max(1_600).optional()
  })
  .strict()
  .describe(
    'Use code_object create for trusted interactive or stateful TSX content. Prefer placement.target {kind:"auto"} when no exact anchor or location was requested. Do not use it for a plain note, titled explanation, or static process diagram.'
  )

const codeObjectRefineRecipeSchema = z
  .object({
    expected_source_hash: z.string().regex(/^sha256:[0-9a-f]{64}$/u),
    kind: z.literal('code_object'),
    name: z.string().trim().min(1).max(120).optional(),
    object_key: z.string().trim().min(1).max(160),
    operation: z.literal('refine'),
    owner_id: z.string().trim().min(1),
    props: plainJsonObjectSchema.optional(),
    source: codeObjectSourceSchema,
    source_format: z.literal('tsx')
  })
  .strict()
  .describe(
    'Use code_object refine only for exact-owner full-source replacement based on the current get_code_object response.'
  )

const recipeSchema = z
  .union([
    z
      .object({
        font_size: z.number().finite().min(8).max(256).optional(),
        kind: z.literal('native_text'),
        max_width: z.number().finite().min(48).max(2_000).optional(),
        name: z.string().trim().min(1).optional(),
        placement: placementSchema.optional(),
        text: z.string().trim().min(1).max(10_000)
      })
      .strict()
      .describe('Use native_text for a short editable Board label, caption, or plain note.'),
    z
      .object({
        body: z.string().trim().min(1).max(1_200),
        kind: z.literal('native_card'),
        name: z.string().trim().min(1).optional(),
        placement: cardPlacementSchema.optional(),
        title: z.string().trim().min(1).max(120),
        width: z.number().finite().min(240).max(640).optional()
      })
      .strict()
      .describe(
        'Use native_card for a titled editable explanation, decision, summary, or bounded idea. Prefer placement.target {kind:"auto"} unless the user requested an anchor, exact point, or bounded region.'
      ),
    z
      .object({
        allow_additional_owner: z.boolean().optional(),
        kind: z.literal('native_diagram'),
        owner_id: z.string().trim().min(1).optional(),
        source: z.string().trim().min(1).max(50_000),
        source_format: z.literal('mermaid'),
        zoom_to_selection: z.boolean().optional()
      })
      .strict()
      .describe(
        'Use native_diagram with Mermaid for a multi-node process, topology, journey, architecture, or state flow.'
      ),
    codeObjectCreateRecipeSchema,
    codeObjectRefineRecipeSchema
  ])
  .describe(
    'Choose the simplest medium that preserves the requested behavior: editable text, titled card, Mermaid diagram, or trusted interactive Code Object.'
  )

const logicalInputShape = {
  anchor_id: z.string().trim().min(1).optional(),
  extension: extensionSchema.optional(),
  intent: z.string().trim().min(1).max(1_000),
  recipe: recipeSchema,
  request_id: z.string().trim().min(1),
  task_id: z.string().trim().min(1).optional(),
  trace_id: z.string().trim().min(1).optional()
}

function validateRecipeAnchor(
  value: { anchor_id?: string; recipe: z.infer<typeof recipeSchema> },
  context: z.RefinementCtx
) {
  if (value.recipe.kind === 'native_text' && !value.anchor_id) {
    context.addIssue({ code: 'custom', message: `${value.recipe.kind} requires anchor_id.` })
  }
  if (
    value.recipe.kind === 'native_card' &&
    Boolean(value.anchor_id) === Boolean(value.recipe.placement?.target)
  ) {
    context.addIssue({
      code: 'custom',
      message: 'native_card requires exactly one of anchor_id or placement.target.'
    })
  }
  if (value.recipe.kind === 'code_object' && value.recipe.operation === 'create') {
    if (Boolean(value.anchor_id) === Boolean(value.recipe.placement?.target)) {
      context.addIssue({
        code: 'custom',
        message: 'code_object create requires exactly one of anchor_id or placement.target.'
      })
    }
  }
  if (value.recipe.kind === 'native_diagram' && value.recipe.owner_id && value.anchor_id) {
    context.addIssue({
      code: 'custom',
      message: 'Diagram refinement cannot combine owner_id with anchor_id.'
    })
  }
  if (
    value.recipe.kind === 'code_object' &&
    value.recipe.operation === 'refine' &&
    value.anchor_id
  ) {
    context.addIssue({
      code: 'custom',
      message: 'Code Object refinement uses recipe.owner_id, not anchor_id.'
    })
  }
}

const flatInputSchema = z
  .object({
    ...exactTargetSchema,
    context_token: z
      .string()
      .trim()
      .min(1)
      .describe('Copy board_context.board_build_base.context_token exactly.'),
    contract: z
      .literal('board-build/v1')
      .describe('Copy board_context.board_build_base.contract exactly.'),
    expected_revision: z
      .number()
      .int()
      .nonnegative()
      .describe('Copy board_context.board_build_base.expected_revision exactly.'),
    ...logicalInputShape
  requestId: string
): SceneNode[] {
  return [...graph.getDescendants(pageId)].filter(
    (node) => authorityCardMarker(node)?.requestId === requestId
  )
}

export function createAuthorityNativeCard(
  document: AuthorityBoardDocument,
  pageId: string,
  operation: AuthorityCardOperation,
  inputDigest: string,
  requestId: string
) {
  const innerWidth = operation.width - CARD_PADDING * 2
  const titleHeight = measuredHeight(
    operation.title,
    TITLE_FONT_SIZE,
    TITLE_LINE_HEIGHT,
    innerWidth
  )
  const bodyHeight = measuredHeight(operation.body, BODY_FONT_SIZE, BODY_LINE_HEIGHT, innerWidth)
  const height = CARD_PADDING * 2 + titleHeight + CARD_GAP + bodyHeight
  if (height > MAX_CARD_HEIGHT)
    throw new Error(`native_card exceeds ${MAX_CARD_HEIGHT} Board units.`)
  const placed = resolveAuthorityFreePlacement({
    clearance: operation.clearance,
    footprint: { height, width: operation.width },
    graph: document.graph,
    pageId,
    target: operation.placementTarget
  })
  const owner = document.graph.createNode('FRAME', pageId, {
    clipsContent: false,
    cornerRadius: 16,
    fills: [solidFill(0.067, 0.094, 0.153)],
    height,
    name: operation.name,
    strokes: [cardStroke()],
    width: operation.width,
    x: placed.bounds.x,
    y: placed.bounds.y
  })
  const title = document.graph.createNode('TEXT', owner.id, {
    fills: [solidFill(0.973, 0.98, 0.988)],
    fontSize: TITLE_FONT_SIZE,
    fontWeight: 600,
    height: titleHeight,
    lineHeight: TITLE_LINE_HEIGHT,
    name: 'Title',
    text: operation.title,
    textAutoResize: 'NONE',
    width: innerWidth,
    x: CARD_PADDING,
    y: CARD_PADDING
  })
  const body = document.graph.createNode('TEXT', owner.id, {
    fills: [solidFill(0.796, 0.835, 0.882)],
    fontSize: BODY_FONT_SIZE,
    fontWeight: 400,
    height: bodyHeight,
    lineHeight: BODY_LINE_HEIGHT,
    name: 'Body',
    text: operation.body,
    textAutoResize: 'NONE',
    width: innerWidth,
    'RECTANGLE',
    100,
    100,
    160,
    120,
    automationTarget.pageId
  )
  automationTarget.store.createShape('RECTANGLE', 308, 100, 720, 520, automationTarget.pageId)
  automationTarget.store.select([anchorId])
  automationTarget.store.undo.clear()
  return { anchorId, automationTarget }
}

describe('Code Object automation', () => {
  test('creates directly on an empty Board from an explicit free-placement target', async () => {
    installBrowserFixture()
    const automationTarget = target()
    const create = createAutomationCodeObjectCreateHandler()
    const base = createArgs(automationTarget, 'unused', 'request:create-free-code-object')
    const created = await create(automationTarget, {
      ...base,
      anchor_id: undefined,
      placement: { ...base.placement, target: { kind: 'auto' } }
    })

    expect(created).toMatchObject({
      placement: { algorithm: 'nearest-free/v1', rejectedCandidates: 0 },
      status: { attention_required: false, command: 'completed', mutation: 'applied' }
    })
    expect(automationTarget.store.graph.getNode(created.owner_id)).toMatchObject({
      height: 520,
      type: 'FRAME',
      width: 720
    })
  })

  test('creates once with anchored collision-free placement and replays across reload', async () => {
    const { anchorId, automationTarget } = anchorTarget()
    const create = createAutomationCodeObjectCreateHandler()
    const args = createArgs(automationTarget, anchorId, 'request:create-signal-constellation')

    const created = await create(automationTarget, args)
    expect(created).toMatchObject({
      receipt: {
        history_label: 'Create code object',
        idempotent_replay: false,
        product_grade_path: true
      },
      readback: {
        code_object: {
          component: {
            object_key: 'signal-constellation',
            source_hash: expect.stringMatching(/^sha256:/)
          },
          reconciliation: { reasons: [], status: 'current' }
        }
      },
      status: { attention_required: false, command: 'completed', mutation: 'applied' }
    })
    expect(created.placement?.rejectedCandidates).toBeGreaterThan(0)
    expect(automationTarget.store.undo.undoLabel).toBe('Create code object')
    const ownerId = created.owner_id
    expect(automationTarget.store.graph.getNode(ownerId)?.type).toBe('FRAME')

    const reloadedGraph = deserializeSceneGraph(
      structuredClone(serializeSceneGraph(automationTarget.store.graph))
    )
    const reloadedStore = createEditorStore(reloadedGraph)
    const reloadedPage = reloadedStore.graph.getNode(automationTarget.pageId)
    if (!reloadedPage) throw new Error('Reloaded test page is missing')
    const reloadedTarget: AutomationTarget = {
      documentId: automationTarget.documentId,
      documentName: automationTarget.documentName,
      pageId: automationTarget.pageId,
      pageName: reloadedPage.name,
      store: reloadedStore
    }
    const replayed = await create(reloadedTarget, args)
