type CapacityProps = {
  interactionEnabled: boolean
  state: Record<string, unknown>
  setState: (
    next:
      | Record<string, unknown>
      | ((current: Record<string, unknown>) => Record<string, unknown>)
  ) => void
}

const MIN_CAPACITY = 4
const MAX_CAPACITY = 20

function clampCapacity(value: number) {
  return Math.min(MAX_CAPACITY, Math.max(MIN_CAPACITY, Math.round(value)))
}

export default function SprintCapacity({ interactionEnabled, state, setState }: CapacityProps) {
  const capacity = clampCapacity(Number(state.capacity ?? 8))

  const updateCapacity = (next: number) => {
    setState((current) => ({ ...current, capacity: clampCapacity(next) }))
  }

  return (
    <main
      style={{
        alignItems: 'center',
        background: 'linear-gradient(145deg, #172033 0%, #101725 100%)',
        border: '1px solid #3b4a66',
        borderRadius: 18,
        boxSizing: 'border-box',
        color: '#f8fafc',
        display: 'grid',
        fontFamily: 'Inter, ui-sans-serif, system-ui, sans-serif',
        gap: 16,
        gridTemplateColumns: '1fr auto',
        height: '100%',
        padding: '22px 24px',
        width: '100%'
      }}
    >
      <section>
        <div style={{ color: '#93c5fd', fontSize: 12, fontWeight: 700, letterSpacing: 1.3 }}>
          SPRINT CAPACITY
        </div>
        <div style={{ fontSize: 30, fontWeight: 750, marginTop: 5 }}>
          {capacity} points
        </div>
        <div style={{ color: '#aab7cc', fontSize: 13, marginTop: 4 }}>
          Adjust the commitment ceiling
        </div>
      </section>

      <div style={{ alignItems: 'center', display: 'flex', gap: 10 }}>
        <button
          aria-label="Decrease capacity"
          disabled={!interactionEnabled || capacity <= MIN_CAPACITY}
          onClick={() => updateCapacity(capacity - 1)}
          style={{
            background: '#25324a',
            border: '1px solid #4c5f80',
            borderRadius: 10,
            color: '#f8fafc',
            cursor: interactionEnabled ? 'pointer' : 'default',
            fontSize: 24,
            height: 42,
            width: 42
          }}
        >
          −
        </button>
        <button
          aria-label="Increase capacity"
          disabled={!interactionEnabled || capacity >= MAX_CAPACITY}
          onClick={() => updateCapacity(capacity + 1)}
          style={{
            background: '#2563eb',
            border: '1px solid #60a5fa',
            borderRadius: 10,
            color: '#ffffff',
            cursor: interactionEnabled ? 'pointer' : 'default',
            fontSize: 24,
            height: 42,
            width: 42
          }}
        >
          +
        </button>
      </div>

      <input
        aria-label="Sprint capacity"
        disabled={!interactionEnabled}
        max={MAX_CAPACITY}
        min={MIN_CAPACITY}
        onChange={(event) => updateCapacity(Number(event.currentTarget.value))}
        onInput={(event) => updateCapacity(Number(event.currentTarget.value))}
        step={1}
        style={{ accentColor: '#60a5fa', gridColumn: '1 / -1', width: '100%' }}
        type="range"
        value={capacity}
      />
    </main>
  )
}

