    "definition_id": "sprint-capacity-control",
    "name": "Sprint capacity control",
    "props": {},
    "source": "type P={interactionEnabled:boolean;state:Record<string,unknown>;setState:(next:Record<string,unknown>|((current:Record<string,unknown>)=>Record<string,unknown>))=>void}\nconst MIN=4\nconst MAX=20\nconst clamp=(value:number)=>Math.min(MAX,Math.max(MIN,Math.round(value)))\nexport default function SprintCapacity({interactionEnabled,state,setState}:P){\n const capacity=clamp(Number(state.capacity??8))\n const update=(next:number)=>setState(current=>({...current,capacity:clamp(next)}))\n return <main style={{alignItems:'center',background:'linear-gradient(145deg,#172033 0%,#101725 100%)',border:'1px solid #3b4a66',borderRadius:18,boxSizing:'border-box',color:'#f8fafc',display:'grid',fontFamily:'Inter,ui-sans-serif,system-ui,sans-serif',gap:16,gridTemplateColumns:'1fr auto',height:'100%',padding:'22px 24px',width:'100%'}}>\n  <section><div style={{color:'#93c5fd',fontSize:12,fontWeight:700,letterSpacing:1.3}}>SPRINT CAPACITY</div><div style={{fontSize:30,fontWeight:750,marginTop:5}}>{capacity} points</div><div style={{color:'#aab7cc',fontSize:13,marginTop:4}}>Adjust the commitment ceiling</div></section>\n  <div style={{alignItems:'center',display:'flex',gap:10}}>\n   <button aria-label='Decrease capacity' disabled={!interactionEnabled||capacity<=MIN} onClick={()=>update(capacity-1)} style={{background:'#25324a',border:'1px solid #4c5f80',borderRadius:10,color:'#f8fafc',cursor:interactionEnabled?'pointer':'default',fontSize:24,height:42,width:42}}>−</button>\n   <button aria-label='Increase capacity' disabled={!interactionEnabled||capacity>=MAX} onClick={()=>update(capacity+1)} style={{background:'#2563eb',border:'1px solid #60a5fa',borderRadius:10,color:'#fff',cursor:interactionEnabled?'pointer':'default',fontSize:24,height:42,width:42}}>+</button>\n  </div>\n  <input aria-label='Sprint capacity' disabled={!interactionEnabled} max={MAX} min={MIN} onChange={event=>update(Number(event.currentTarget.value))} onInput={event=>update(Number(event.currentTarget.value))} step={1} style={{accentColor:'#60a5fa',gridColumn:'1 / -1',width:'100%'}} type='range' value={capacity}/>\n </main>\n}",
    "source_hash": "sha256:2c3fbcdf3d9ca606552094b3743b07d8c40b45435b34cc41a6ad274cb1d8847d",
    "source_length": 2096,
    "state": {
      "capacity": 8
    }
  },
  "frame": {
    "height": 190,
